// Generates the JavaScript and Python order schema from schema/order.json.
//   node schema/generate.mjs           write the generated files
//   node schema/generate.mjs --check   write nothing; exit 1 listing each file that differs
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = fileURLToPath(new URL('..', import.meta.url));
const SCHEMA_PATH = fileURLToPath(new URL('order.json', import.meta.url));
const NOTICE = 'GENERATED by schema/generate.mjs from schema/order.json. Do not edit.';

export const JS_OUTPUT = 'department/lib/order-schema.mjs';
export const PY_OUTPUT = 'foundry/order_schema.py';

// A JSON string literal is also a valid JavaScript and Python string literal.
const quote = (s) => JSON.stringify(s);
const jsArray = (items) => `[${items.map(quote).join(', ')}]`;
const jsKey = (key) => (/^[A-Za-z_$][\w$]*$/.test(key) ? key : quote(key));
const pyBlock = (open, items, close) => [open, ...items.map((s) => `    ${quote(s)},`), close];

export function loadSchema(file = SCHEMA_PATH) {
  return JSON.parse(fs.readFileSync(file, 'utf8'));
}

// acceptanceItem -> LIMIT_ACCEPTANCE_ITEM
export function limitConstant(key) {
  return `LIMIT_${key.replace(/([a-z0-9])([A-Z])/g, '$1_$2').toUpperCase()}`;
}

export function renderJs(schema) {
  return [
    `// ${NOTICE}`,
    `export const BATCH_STATUSES = ${jsArray(schema.batchStatuses)};`,
    `export const RESULT_STATES = ${jsArray(schema.resultStates)};`,
    `export const TERMINAL_RESULT = new Set(${jsArray(schema.terminalResults)});`,
    `export const OPEN_BATCH = new Set(${jsArray(schema.openBatches)});`,
    `export const SIZES = ${jsArray(schema.sizes)};`,
    `export const SUBTASK_FIELDS = ${jsArray(schema.subtaskFields)};`,
    'export const LIMITS = Object.freeze({',
    ...Object.entries(schema.limits).map(([key, value]) => `  ${jsKey(key)}: ${value},`),
    '});',
    '',
  ].join('\n');
}

export function renderPython(schema) {
  const limits = Object.entries(schema.limits);
  const names = [
    'BATCH_STATUSES', 'RESULT_STATES', 'SIZES', 'SUBTASK_FIELDS', 'TERMINAL_RESULT', 'OPEN_BATCH', 'LIMITS',
    ...limits.map(([key]) => limitConstant(key)),
  ];
  return [
    `# ${NOTICE}`,
    '"""Every Foundry batch and order field and limit, shared with the JavaScript side.',
    '',
    'Edit schema/order.json and run ``node schema/generate.mjs``; never edit this file.',
    '"""',
    '',
    ...pyBlock('BATCH_STATUSES = (', schema.batchStatuses, ')'),
    ...pyBlock('RESULT_STATES = (', schema.resultStates, ')'),
    ...pyBlock('SIZES = (', schema.sizes, ')'),
    ...pyBlock('SUBTASK_FIELDS = (', schema.subtaskFields, ')'),
    ...pyBlock('TERMINAL_RESULT = frozenset([', schema.terminalResults, '])'),
    ...pyBlock('OPEN_BATCH = frozenset([', schema.openBatches, '])'),
    '',
    'LIMITS = {',
    ...limits.map(([key, value]) => `    ${quote(key)}: ${value},`),
    '}',
    '',
    ...limits.map(([key, value]) => `${limitConstant(key)} = ${value}`),
    '',
    ...pyBlock('__all__ = [', names, ']'),
    '',
  ].join('\n');
}

function generatedFiles(schema) {
  return [[JS_OUTPUT, renderJs(schema)], [PY_OUTPUT, renderPython(schema)]];
}

export function writeGenerated(schema, root = ROOT) {
  for (const [rel, text] of generatedFiles(schema)) {
    const target = path.join(root, rel);
    fs.mkdirSync(path.dirname(target), { recursive: true });
    fs.writeFileSync(target, text);
  }
}

// Generated files that are missing or differ from the rendering. A Windows checkout may
// hold CRLF line endings, which do not count as a difference.
export function differences(schema, root = ROOT) {
  return generatedFiles(schema)
    .filter(([rel, text]) => {
      const target = path.join(root, rel);
      return !fs.existsSync(target) || fs.readFileSync(target, 'utf8').replace(/\r\n/g, '\n') !== text;
    })
    .map(([rel]) => rel);
}

function main(args) {
  if (args.some((arg) => arg !== '--check')) {
    console.error('usage: node schema/generate.mjs [--check]');
    return 2;
  }
  const schema = loadSchema();
  if (args.length === 0) {
    writeGenerated(schema);
    return 0;
  }
  const stale = differences(schema);
  for (const rel of stale) console.log(`differs: ${rel}`);
  return stale.length ? 1 : 0;
}

if (process.argv[1] && fs.realpathSync(process.argv[1]) === fileURLToPath(import.meta.url)) {
  process.exitCode = main(process.argv.slice(2));
}
